"""Per-class query database D for unlabeled images (paper Sec. 3.2.1, Sec. 3.4.2, Fig. 3).

"For unlabeled images, we maintain a database of precomputed queries per class, generated by incorporating
distinguishing attributes into segmentation query templates." Each class owns a list of semantically
equivalent queries, e.g. for Cars: "Segment the sedan used for daily commute", ..., "Segment all small,
low-height vehicles typically used for personal transportation." (Fig. 3). During training K = 7 distinct
queries of the pseudo-labeled class are drawn: one trains the model, the other K-1 measure the consistency
of its predictions (Sec. 3.2.1).

Rules every query must obey (:func:`check_query`; they follow from "all queries denote the same pixels"):

* it is a segmentation instruction (the word "segment") and contains no special token or markup;
* it identifies its class from appearance and function, so it is NOT the bare class name, and it names no
  other class of the dataset (the model must not be pointed at a confusable class);
* it does not restrict the class by an incidental attribute (clothing, accessory, colour, activity) and does not
  lean on a word that belongs to a confusable class ("signal" in a pole query, "bike" in a rider query): the
  word lists below (:data:`RESTRICTING_TERMS`, :data:`CONFUSABLE_TERMS`) are a heuristic, and a list of
  sub-types is only acceptable when it exhausts the class, which only a reader can judge;
* it covers every instance of the class: plural or mass phrasing, no count, no number word, no singular
  deictic start ("Segment this ..."), and no position word (left, above, near, ...), since a position or a
  count would select a subset of the pixels.

File format: ``{"dataset": ..., "classes": {"<id>": {"name": ..., "queries": [...]}}, "meta": {...}}``.
"""
from __future__ import annotations

import json
import logging
import random
import re
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple

from cora import constants as C
from cora.config import REPO_ROOT, Config
from cora.data import templates
from cora.data.adapters import atomic_write

LOG = logging.getLogger(__name__)
ASSET_DIR = REPO_ROOT / "assets" / "query_db"
MIN_QUERIES = 12  # shipped databases hold at least this many queries per class (K = 7 must be drawable)

POSITION_WORDS = (
    "left", "right", "top", "bottom", "front", "behind", "near", "nearby", "next to", "beside", "above", "below",
    "beneath", "underneath", "under", "upper", "lower", "middle", "center", "centre", "corner", "background",
    "foreground", "adjacent", "alongside", "along", "overhead", "between", "opposite", "around", "surrounding",
    "across", "ahead", "inside", "outside", "atop", "beyond", "in the distance",
)
COUNT_WORDS = (
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "single", "pair", "couple",
    "dozen", "both", "first", "second", "third",
)
# Incidental attributes that select a subset of any class ("pedestrians with backpacks", "helmeted cyclists").
RESTRICTING_TERMS = (
    "wearing", "wear", "helmet", "helmeted", "backpack", "umbrella", "pram", "stroller", "shopping", "graffiti",
    "graffiti-covered", "basket", "mudguard", "flashing", "dog",
)
_COLOURS = ("yellow", "red", "blue", "green", "white", "black", "orange", "grey", "gray", "amber", "purple", "brown", "pink")
_ACTIVITIES = ("walk", "walking", "walkers", "walker", "stand", "standing", "stroll", "strolling", "jogging", "queueing",
               "chatting", "waiting", "talk", "talking", "pushing")
# Words of one class that must not appear in the queries of another, per dataset and class id: the model
# could be pointed at the confusable class. Colours and activities restrict a class to a subset.
CONFUSABLE_TERMS: Dict[str, Dict[int, Tuple[str, ...]]] = {
    "cityscapes": {
        0: ("pavement", "footpath", "walkway", "kerb", "curb"),
        1: ("carriageway", "tarmac", "asphalt", "bituminous"),
        2: _COLOURS,
        3: _COLOURS + ("house", "home", "dwelling", "fencing", "railing", "picket"),
        4: _COLOURS + ("rail", "railway", "masonry", "brick", "concrete"),
        5: _COLOURS + ("signal", "board", "sign", "signboard", "traffic", "plate", "panel"),
        6: ("pole", "post", "mast", "sign", "signboard", "board"),
        7: _COLOURS + ("post", "mast", "signal", "lamp", "light"),
        8: ("grass", "lawn", "turf", "meadow", "soil", "dirt", "sand", "mown"),
        9: ("tree", "bush", "hedge", "shrub", "foliage", "woody", "leaf", "leaves", "forest"),
        11: _COLOURS + _ACTIVITIES + ("cyclist", "biker", "motorcyclist", "rider"),
        12: _COLOURS + ("bike", "bicycle", "scooter", "e-scooter", "moped", "motorbike", "cycle", "pedal", "pedalling",
                        "throttle", "pedestrian", "walker"),
        13: _COLOURS + ("pick-up", "pickup", "lorry", "freight", "cargo", "coach"),
        14: _COLOURS + ("van", "minivan", "sedan", "taxi", "passenger", "commuter"),
        15: _COLOURS + ("tram", "streetcar", "rail", "railway", "locomotive", "track", "coach", "minibus"),
        16: _COLOURS + ("bus", "coach", "road", "street"),
        17: _COLOURS + ("pedal", "pushbike", "bicycle", "muscle", "mudguard"),
        18: _COLOURS + ("motor", "engine", "fuel", "moped", "scooter", "motorbike", "petrol", "throttle", "exhaust"),
    },
}
_SPECIAL = re.compile(r"[<>\[\]{}]|SSEG|\bREF\b", re.IGNORECASE)
_SINGULAR_START = re.compile(r"^\s*(?:please\s+)?segment\s+(?:a|an|this|that|one|it)\b", re.IGNORECASE)
_LEAD_IN = re.compile(r"^(?:can you |could you |please |kindly )*(?:segment|find and segment)\s+", re.IGNORECASE)
_FILLER = {"the", "all", "every", "each", "of", "any"}


def _word_regex(words: Sequence[str]) -> re.Pattern:
    """Whole-word, case-insensitive match of any of ``words`` (longest first)."""
    return re.compile(r"\b(?:" + "|".join(re.escape(w) for w in sorted(set(words), key=len, reverse=True)) + r")\b", re.IGNORECASE)


_POSITION = _word_regex(POSITION_WORDS)
_RESTRICTING = re.compile(r"\b(?:" + "|".join(re.escape(w) for w in RESTRICTING_TERMS) + r")(?:s|es)?\b", re.IGNORECASE)


def _confusable_pattern(dataset: str, class_id: int) -> Optional[re.Pattern]:
    terms = CONFUSABLE_TERMS[dataset].get(class_id)
    if not terms:
        return None
    return re.compile(r"\b(?:" + "|".join(re.escape(t) for t in sorted(set(terms), key=len, reverse=True)) + r")(?:s|es)?\b", re.IGNORECASE)
# "-" is not a word boundary here on purpose: "two-cars" is still a count. The one exemption is a class-defining
# wheel count in a compound modifier ("four-wheeled vehicle", "two-wheeler"), which names an attribute of the
# class, not a number of instances (Fig. 5: "Segment the four-wheeled vehicle designed for everyday private
# transport").
_COUNT = re.compile(
    r"\d|(?<![A-Za-z])(?:" + "|".join(COUNT_WORDS) + r")(?![A-Za-z])(?!-wheel(?:ed|ers?)?(?![A-Za-z]))", re.IGNORECASE)


def normalise(text: str) -> str:
    """Lower-cased text with punctuation collapsed to single spaces (key for duplicate checks)."""
    return " ".join(re.sub(r"[^a-z0-9]+", " ", text.lower()).split())


_EXTRA_NAME_FORMS = {"cityscapes": {0: ("roads",), 11: ("persons",)}}


def _name_forms(dataset: str, class_id: int) -> List[str]:
    """Every phrase that names a class: its id name, query phrases, singular and plural forms."""
    names = {C.class_names(dataset)[class_id], *templates.singular_phrases(dataset, class_id)}
    names.update(templates.class_phrases(dataset, class_id))
    names.update(templates.plural_phrases(dataset, class_id))
    names.update(_EXTRA_NAME_FORMS[dataset].get(class_id, ()))
    return sorted(names, key=len, reverse=True)


def other_class_pattern(dataset: str, class_id: int) -> Optional[re.Pattern]:
    """Regex matching a mention of any class of the dataset other than ``class_id``."""
    own = {normalise(f) for f in _name_forms(dataset, class_id)}
    forms = [f for other in range(len(C.class_names(dataset))) if other != class_id
             for f in _name_forms(dataset, other) if normalise(f) not in own]
    return _word_regex(forms) if forms else None


def check_query(query: str, dataset: str, class_id: int) -> List[str]:
    """Reasons why ``query`` is not a valid query of class ``class_id`` (empty list = valid)."""
    problems: List[str] = []
    text = query.strip()
    if not text:
        return ["empty"]
    if _SPECIAL.search(text) or any(t in text for t in (C.IMAGE_TOKEN, C.SEG_TOKEN, C.REF_TOKEN, C.REF_MASK_TOKEN, C.REF_BOX_TOKEN)):
        problems.append("contains a special token or markup")
    if not re.search(r"\bsegment\b", text, re.IGNORECASE):
        problems.append('is not a segmentation instruction (no word "segment")')
    position = _POSITION.search(text)
    if position:
        problems.append(f"contains the position word {position.group(0)!r}")
    count = _COUNT.search(text)
    if count:
        problems.append(f"contains the count / number word {count.group(0)!r}")
    if _SINGULAR_START.match(text):
        problems.append("starts with a singular determiner (refers to one instance)")
    core = normalise(_LEAD_IN.sub("", text))
    core = " ".join(w for w in core.split() if w not in _FILLER)
    if core in {normalise(f) for f in _name_forms(dataset, class_id)}:
        problems.append("is just the class name")
    other = other_class_pattern(dataset, class_id)
    mention = other.search(text) if other else None
    if mention:
        problems.append(f"names another class ({mention.group(0)!r})")
    restricting = _RESTRICTING.search(text)
    if restricting:
        problems.append(f"restricts the class by an incidental attribute ({restricting.group(0)!r})")
    confusable = _confusable_pattern(dataset, class_id)
    hit = confusable.search(text) if confusable else None
    if hit:
        problems.append(f"uses {hit.group(0)!r}, a word of a confusable class or a restricting attribute")
    return problems


class QueryDB:
    """Queries per class id (database D of Sec. 3.2.1)."""

    def __init__(self, queries: Dict[int, List[str]], dataset: str, *, meta: Optional[dict] = None) -> None:
        if dataset not in C.DATASETS:
            raise ValueError(f"unknown dataset {dataset!r}; expected one of {C.DATASETS}")
        names = C.class_names(dataset)
        self.dataset = dataset
        self.meta: dict = dict(meta or {})
        self._queries: Dict[int, List[str]] = {}
        for class_id, items in queries.items():
            class_id = int(class_id)
            if not 0 <= class_id < len(names):
                raise ValueError(f"class id {class_id} is outside 0..{len(names) - 1} for {dataset}")
            items = list(items)
            if not all(isinstance(q, str) and q.strip() for q in items):
                raise ValueError(f"class {names[class_id]}: queries must be non-empty strings")
            keys = [normalise(q) for q in items]
            if len(set(keys)) != len(keys):
                raise ValueError(f"class {names[class_id]}: duplicate queries")
            self._queries[class_id] = items

    # ---- access ------------------------------------------------------------------------------
    def class_ids(self) -> List[int]:
        return sorted(self._queries)

    def queries(self, class_id: int) -> List[str]:
        """All queries of a class (a copy)."""
        if class_id not in self._queries:
            raise ValueError(f"the query database holds no class {class_id}; it has {self.class_ids()}")
        return list(self._queries[class_id])

    def sample(self, class_id: int, k: int, rng: random.Random) -> List[str]:
        """``k`` distinct queries of a class; ``ValueError`` if the class has fewer (Sec. 3.2.1: K = 7)."""
        items = self.queries(class_id)
        if k < 0 or k > len(items):
            raise ValueError(f"class {C.class_names(self.dataset)[class_id]} has {len(items)} queries, cannot draw {k} distinct ones")
        return rng.sample(items, k)

    # ---- validation --------------------------------------------------------------------------
    def problems(self, min_queries: int = MIN_QUERIES) -> List[str]:
        """Every violation of the query rules, as readable lines (empty list = the database is valid)."""
        names = C.class_names(self.dataset)
        found: List[str] = []
        for class_id in range(len(names)):
            items = self._queries.get(class_id)
            if items is None:
                found.append(f"{names[class_id]}: no queries")
                continue
            if len(items) < min_queries:
                found.append(f"{names[class_id]}: {len(items)} queries, need at least {min_queries}")
            for query in items:
                found.extend(f"{names[class_id]}: {query!r} {reason}" for reason in check_query(query, self.dataset, class_id))
        return found

    def validate(self, min_queries: int = MIN_QUERIES) -> None:
        """Raise ``ValueError`` listing the violations, if any."""
        found = self.problems(min_queries)
        if found:
            raise ValueError("invalid query database:\n  " + "\n  ".join(found))

    # ---- storage -----------------------------------------------------------------------------
    def to_dict(self) -> dict:
        names = C.class_names(self.dataset)
        return {
            "dataset": self.dataset,
            "classes": {str(c): {"name": names[c], "queries": list(self._queries[c])} for c in self.class_ids()},
            "meta": self.meta,
        }

    def save(self, path: Path) -> None:
        atomic_write(Path(path), (json.dumps(self.to_dict(), indent=2, ensure_ascii=False) + "\n").encode("utf-8"))

    @classmethod
    def load(cls, path: Path) -> "QueryDB":
        path = Path(path)
        if not path.is_file():
            raise FileNotFoundError(f"query database not found: {path}")
        data = json.loads(path.read_text(encoding="utf-8"))
        try:
            dataset, classes = data["dataset"], data["classes"]
        except (KeyError, TypeError):
            raise ValueError(f"{path}: expected an object with 'dataset' and 'classes'") from None
        names = C.class_names(dataset) if dataset in C.DATASETS else ()
        queries: Dict[int, List[str]] = {}
        for key, entry in classes.items():
            class_id = int(key)
            if class_id < len(names) and entry.get("name") not in (None, names[class_id]):
                raise ValueError(f"{path}: class {class_id} is named {entry.get('name')!r}, expected {names[class_id]!r}")
            queries[class_id] = entry["queries"]
        return cls(queries, dataset, meta=data.get("meta"))

    @classmethod
    def for_config(cls, cfg: Config) -> "QueryDB":
        """``cfg.query_db_path`` when it exists, else the shipped ``assets/query_db/<dataset>.json``."""
        path = cfg.query_db_path
        if not path.is_file():
            path = shipped_path(cfg.data.dataset)
        db = cls.load(path)
        if db.dataset != cfg.data.dataset:
            raise ValueError(f"{path} is a {db.dataset} database but the configuration uses {cfg.data.dataset}")
        if db.meta.get("source") == "hand-written":
            LOG.info("query database %s is hand-written, not LLM-generated as in Sec. 3.4.2 of the paper", path)
        return db


def shipped_path(dataset: str) -> Path:
    """Location of the database shipped with the repository."""
    if dataset not in C.DATASETS:
        raise ValueError(f"unknown dataset {dataset!r}; expected one of {C.DATASETS}")
    return ASSET_DIR / f"{dataset}.json"
